import{_ as o,a0 as p,w as s,s as d,ao as r,I as a,x as e,a1 as l,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"五个 Linux 下用户空间的调试工具 | LCTT x X-CMD","titleTemplate":false,"description":"五个 Linux 下用户空间的调试工具 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"五个 Linux 下用户空间的调试工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"五个 Linux 下用户空间的调试工具 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141229 5 User Space Debugging Tools in Linux","title":"五个 Linux 下用户空间的调试工具","tag":"201503","desc":""},"relativePath":"201503/20141229 5 User Space Debugging Tools in Linux.md","filePath":"[post].md"}'),g={name:"201503/20141229 5 User Space Debugging Tools in Linux.md"};function c(u,t,h,m,b,x){const n=p("Link");return s(),d("div",null,[t[19]||(t[19]=r(`<h1 id="五个-linux-下用户空间的调试工具" tabindex="-1">五个 Linux 下用户空间的调试工具 <a class="header-anchor" href="#五个-linux-下用户空间的调试工具" aria-label="Permalink to “五个 Linux 下用户空间的调试工具”">​</a></h1><p>根据定义，调试工具是那些那些使我们能够监测、控制和纠正其他程序的程序。我们为什么应该用调试工具呢? 在有些情况下，运行一些程序的时候我们会被卡住，我们需要明白究竟发生了什么。 例如，我们正在运行应用程序，它产生了一些错误消息。要修复这些错误，我们应该先找出为什么产生这些错误的消息和这些错误消息从哪里产生的。 一个应用程序可能突然挂起，我们必须了解其他什么进程同时在运行。我们可能还必须弄清楚某个进程挂起的时候在做什么。为了剖析这些细节， 我们需要调试工具的帮助。</p><p>有几个Linux下的用户空间调试工具和技术，它们用来分析用户空间的问题相当有用。它们是:</p><ul><li><strong>&#39;print&#39; 语句</strong></li><li><strong>查询 (/proc, /sys 等)</strong></li><li><strong>跟踪 (strace/ltrace)</strong></li><li><strong>Valgrind (memwatch)</strong></li><li><strong>GDB</strong></li></ul><p>让我们一个个地了解。</p><h3 id="_1-print-语句" tabindex="-1">1.&#39;print&#39; 语句 <a class="header-anchor" href="#_1-print-语句" aria-label="Permalink to “1.&#39;print&#39; 语句”">​</a></h3><p>这是一个基本的原始的调试问题的方法。 我们可以在程序中插入print语句来了解控制流和变量值。 虽然这是一个简单的技术， 但它有一些缺点。 程序需要进行编辑以添加&#39;print&#39;语句，然后必须重新编译，重新运行来获得输出。 如果要调试的程序相当大，这是一个耗时的方法。</p><h3 id="_2-查询" tabindex="-1">2. 查询 <a class="header-anchor" href="#_2-查询" aria-label="Permalink to “2. 查询”">​</a></h3><p>在某些情况下，我们需要弄清楚在一个运行在内核中的进程的状态和内存映射。为了获得这些信息，我们不需要在内核中插入任何代码。 相反，可以用 /proc 文件系统。</p><p>/proc 是一个伪文件系统，系统一启动运行就收集着运行时系统的信息 (cpu信息, 内存容量等)。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/proc-output.png" alt="output of &#39;ls /proc&#39;"></p><p><em>&#39;ls /proc&#39;的输出</em></p><p>正如你看到的, 系统中运行的每一个进程在/proc文件系统中有一个以进程id命名的项。每个进程的细节信息可以在进程id对应的目录下的文件中获得。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/proc-pid.png" alt="output of &#39;ls /proc/pid&#39;"></p><p><em>&#39;ls /proc/pid&#39;的输出</em></p><p>解释/proc文件系统内的所有条目超出了本文的范围。一些有用的列举如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- /proc/cmdline -&gt; 内核命令行</span></span>
<span class="line"><span>- /proc/cpuinfo -&gt; 关于处理器的品牌，型号信息等</span></span>
<span class="line"><span>- /proc/filesystems -&gt; 文件系统的内核支持的信息</span></span>
<span class="line"><span>- /proc/&lt;pid&gt;/cmdline -&gt; 命令行参数传递到当前进程</span></span>
<span class="line"><span>- /proc/&lt;pid&gt;/mem -&gt; 当前进程持有的内存</span></span>
<span class="line"><span>- /proc/&lt;pid&gt;/status -&gt; 当前进程的状态</span></span></code></pre></div><h3 id="_3-跟踪" tabindex="-1">3. 跟踪 <a class="header-anchor" href="#_3-跟踪" aria-label="Permalink to “3. 跟踪”">​</a></h3><p>strace的和ltrace是两个在Linux中用来追踪程序的执行细节的跟踪工具。</p><h4 id="strace" tabindex="-1">strace: <a class="header-anchor" href="#strace" aria-label="Permalink to “strace:”">​</a></h4><p>strace拦截和记录系统调用及其接收的信号。对于用户，它显示了系统调用、传递给它们的参数和返回值。strace的可以附着到已在运行的进程或一个新的进程。它作为一个针对开发者和系统管理员的诊断、调试工具是很有用的。它也可以用来当做一个通过跟踪不同的程序调用来了解系统的工具。这个工具的好处是不需要源代码，程序也不需要重新编译。</p><p>使用strace的基本语法是：</p><p><strong>strace 命令</strong></p><p>strace有各种各样的参数。可以检查看strace的手册页来获得更多的细节。</p><p>strace的输出非常长，我们通常不会对显示的每一行都感兴趣。我们可以用&#39;-e expr&#39;选项来过滤不想要的数据。</p><p>用 &#39;-p pid&#39; 选项来绑到运行中的进程.</p><p>用&#39;-o&#39;选项，命令的输出可以被重定向到文件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/strace-output.png" alt="output of strace filtering only the open system call"></p><p><em>strace过滤成只有系统调用的输出</em></p><h4 id="ltrace" tabindex="-1">ltrace: <a class="header-anchor" href="#ltrace" aria-label="Permalink to “ltrace:”">​</a></h4><p>ltrace跟踪和记录一个进程的动态（运行时）库的调用及其收到的信号。它也可以跟踪一个进程所作的系统调用。它的用法是类似与strace。</p><p><strong>ltrace command</strong></p><p>&#39;-i&#39; 选项在调用库时打印指令指针。</p><p>&#39;-S&#39; 选项被用来现实系统调用和库调用</p><p>所有可用的选项请参阅ltrace手册。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/ltrace-output.png" alt="output of ltrace capturing &#39;strcmp&#39; library call"></p><p><em>ltrace捕捉&#39;STRCMP&#39;库调用的输出</em></p><h3 id="_4-valgrind" tabindex="-1">4. Valgrind <a class="header-anchor" href="#_4-valgrind" aria-label="Permalink to “4. Valgrind”">​</a></h3><p>Valgrind是一套调试和分析工具。它的一个被广泛使用的默认工具——&#39;Memcheck&#39;——可以拦截malloc()，new()，free()和delete()调用。换句话说，它在检测下面这些问题非常有用：</p><ul><li>内存泄露</li><li>重释放</li><li>访问越界</li><li>使用未初始化的内存</li><li>使用已经被释放的内存等。</li></ul><p>它直接通过可执行文件运行。</p><p>Valgrind也有一些缺点，因为它增加了内存占用，会减慢你的程序。它有时会造成误报和漏报。它不能检测出静态分配的数组的访问越界问题。</p>`,42)),a("p",null,[t[1]||(t[1]=e("为了使用它，首先请",-1)),l(n,{href:"http://valgrind.org/downloads.html"},{default:i(()=>[...t[0]||(t[0]=[e("下载",-1)])]),_:1}),t[2]||(t[2]=e("并安装在你的系统上。可以使用操作系统上的包管理器来安装。",-1))]),t[20]||(t[20]=r(`<p>使用命令行安装需要解压缩和解包下载的文件。</p><pre><code>tar -xjvf valgring-x.y.z.tar.bz2 (where x.y.z is the version number you are trying to install)
</code></pre><p>进入新创建的目录（的valgrind-XYZ）内运行以下命令：</p><pre><code>./configure
make
make install
</code></pre><p>让我们通过一个小程序(test.c)来理解valgrind怎么工作的:</p><pre><code>#include &lt;stdio.h&gt;

void f(void)

{
int x = malloc(10 * sizeof(int));

x[10] = 0;
}

int main()
{
f();
return 0;
}
</code></pre><p>编译程序:</p><pre><code>gcc -o test -g test.c
</code></pre><p>现在我们有一个可执行文件叫做&#39;test&#39;。我们现在可以用valgrind来检测内存错误：</p><pre><code>valgrind –tool=memcheck –leak-check=yes test
</code></pre><p>这是valgrind呈现错误的输出：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/Valgrind.png" alt="output of valgrind showing heap block overrun and memory leak"></p><p><em>valgrind显示堆溢出和内存泄漏的输出</em></p><p>正如我们在上面看到的消息，我们正在试图访问函数f未分配的内存以及分配尚未释放的内存。</p><h3 id="_5-gdb" tabindex="-1">5. GDB <a class="header-anchor" href="#_5-gdb" aria-label="Permalink to “5. GDB”">​</a></h3><p>GDB是来自自由软件基金会的调试器。它对定位和修复代码中的问题很有帮助。当被调试的程序运行时，它给用户控制权去执行各种动作， 比如:</p><ul><li>启动程序</li><li>停在指定位置</li><li>停在指定的条件</li><li>检查所需信息</li><li>改变程序中的数据 等。</li></ul><p>你也可以将一个崩溃的程序coredump附着到GDB并分析故障的原因。</p><p>GDB提供很多选项来调试程序。 然而，我们将介绍一些重要的选择，来感受如何开始使用GDB。</p>`,19)),a("p",null,[t[4]||(t[4]=e("如果你还没有安装GDB，可以在这里下载：",-1)),l(n,{href:"http://www.gnu.org/software/gdb/download/"},{default:i(()=>[...t[3]||(t[3]=[e("GDB官方网站",-1)])]),_:1}),t[5]||(t[5]=e("。",-1))]),t[21]||(t[21]=r(`<h4 id="编译程序" tabindex="-1">编译程序: <a class="header-anchor" href="#编译程序" aria-label="Permalink to “编译程序:”">​</a></h4><p>为了用GDB调试程序，必须使用gcc的&#39;-g&#39;选项进行编译。这将以操作系统的本地格式产生调试信息，GDB利用这些信息来工作。</p><p>下面是一个简单的程序（example1.c）执行被零除用来显示GDB的用法:</p><pre><code>#include
int divide()
{
int x=5, y=0;
return x / y;
}

int main()
{
divide();
}
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gdb-example.png" alt="An example showing usage of gdb"></p><p><em>展示GDB用法的例子</em></p><h4 id="调用-gdb" tabindex="-1">调用 GDB: <a class="header-anchor" href="#调用-gdb" aria-label="Permalink to “调用 GDB:”">​</a></h4><p>通过在命令行中执行&#39;gdb&#39;来启动gdb:</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gdb.png" alt="invoking gdb"></p><p><em>调用 gdb</em></p><p>调用后, 它将等待终端命令并执行，直到退出。</p><p>如果一个进程已经在运行，你需要将GDB连接到它上面，可以通过指定进程ID来实现。假设程序已经崩溃，要分析问题的原因，则用GDB分析core文件。</p><h4 id="启动程序" tabindex="-1">启动程序: <a class="header-anchor" href="#启动程序" aria-label="Permalink to “启动程序:”">​</a></h4><p>一旦你在GDB里面，使用&#39;run&#39;命令来启动程序进行调试。</p><h4 id="给程序传参数" tabindex="-1">给程序传参数: <a class="header-anchor" href="#给程序传参数" aria-label="Permalink to “给程序传参数:”">​</a></h4><p>使用&#39;set args&#39;给你的程序传参数，当程序下次运行时将获得该参数。&#39;show args&#39;将显示传递给程序的参数。</p><h4 id="检查堆栈" tabindex="-1">检查堆栈: <a class="header-anchor" href="#检查堆栈" aria-label="Permalink to “检查堆栈:”">​</a></h4><p>每当程序停止，任何人想明白的第一件事就是它为什么停止，以及怎么停在那里的。该信息被称为反向跟踪。由程序产生每个函数调用和局部变量，传递的参数，调用位置等信息一起存储在堆栈内的数据块种，被称为一帧。我们可以使用GDB来检查所有这些数据。 GDB从最底层的帧开始给这些帧编号。</p><ul><li><strong>bt</strong>: 打印整个堆栈的回溯</li><li><strong>bt <code>&lt;n&gt;</code></strong> 打印n个帧的回溯</li><li><strong>frame <code>&lt;frame number&gt;</code></strong>: 切换到指定的帧，并打印该帧</li><li><strong>up <code>&lt;n&gt;</code></strong>: 上移&#39;n&#39;个帧</li><li><strong>down <code>&lt;n&gt;</code></strong>: 下移&#39;n&#39;个帧 ( n默认是1)</li></ul><h4 id="检查数据" tabindex="-1">检查数据: <a class="header-anchor" href="#检查数据" aria-label="Permalink to “检查数据:”">​</a></h4><p>程序的数据可以在里面GDB使用&#39;print&#39;命令进行检查。例如，如果&#39;x&#39;是调试程序内的变量，&#39;print x&#39;会打印x的值。</p><h4 id="检查源码" tabindex="-1">检查源码: <a class="header-anchor" href="#检查源码" aria-label="Permalink to “检查源码:”">​</a></h4><p>源码可以在GDB中打印。默认情况下，&#39;list&#39;命令会打印10行代码。</p><ul><li><strong>list <code>&lt;linenum&gt;</code></strong>: 列出&#39;linenum&#39;行周围的源码</li><li><strong>list <code>&lt;function&gt;</code></strong>: 从&#39;function&#39;开始列出源码</li><li><strong>disas <code>&lt;function&gt;</code></strong>: 显示该函数机器代码</li></ul><h4 id="停止和恢复程序" tabindex="-1">停止和恢复程序: <a class="header-anchor" href="#停止和恢复程序" aria-label="Permalink to “停止和恢复程序:”">​</a></h4><p>使用GDB，我们可以在必要的地方设置断点，观察点等来停止程序。</p><ul><li><strong>break <code>&lt;location&gt;</code></strong>: 在&#39;location&#39;设置一个断点。当在程序执行到这里时断点将被击中，控制权被交给用户。</li><li><strong>watch <code>&lt;expr&gt;</code></strong>: 当&#39;expr&#39;被程序写入而且它的值发生变化时GDB将停止</li><li><strong>catch <code>&lt;event&gt;</code></strong>: 当&#39;event&#39;发生时GDB停止</li><li><strong>disable <code>&lt;breakpoint&gt;</code></strong>: 禁用指定断点</li><li><strong>enable <code>&lt;breakpoint&gt;</code></strong>: 启用指定断点</li><li><strong>delete <code>&lt;breakpoint&gt;</code></strong>: 删除 断点/观察点/捕获点。 如果没有传递参数默认操作是在所有的断点</li><li><strong>step</strong>: 一步一步执行程序</li><li><strong>continue</strong>: 继续执行程序，直到执行完毕</li></ul><h4 id="退出-gdb" tabindex="-1">退出 GDB: <a class="header-anchor" href="#退出-gdb" aria-label="Permalink to “退出 GDB:”">​</a></h4><p>用&#39;quit&#39;命令还从GDB中退出。</p><p>GDB还有更多的可用选项。里面GDB使用help选项了解更多详情。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gdb-help.png" alt="getting help within gdb"></p><p><em>在GDB中获得帮助</em></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在这篇文章中，我们已经看到不同类型的Linux用户空间的调试工具。总结以上所有内容，如下是什么时候使用该什么的快速指南：</p><ul><li>基本调试，获得关键变量 - print 语句</li><li>获取有关文件系统支持，可用内存，CPU，运行程序的内核状态等信息 - 查询 /proc 文件系统</li><li>最初的问题诊断，系统调用或库调用的相关问题，了解程序流程 – strace / ltrace</li><li>应用程序内存空间的问题 – valgrind</li><li>检查应用程序运行时的行为，分析应用程序崩溃 – gdb</li></ul><hr>`,36)),a("p",null,[t[7]||(t[7]=e("via: ",-1)),l(n,{href:"http://linoxide.com/linux-how-to/user-space-debugging-tools-linux/"},{default:i(()=>[...t[6]||(t[6]=[e("http://linoxide.com/linux-how-to/user-space-debugging-tools-linux/",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("作者：",-1)),l(n,{href:"http://linoxide.com/author/bnpoornima/"},{default:i(()=>[...t[8]||(t[8]=[e("B N Poornima",-1)])]),_:1}),t[12]||(t[12]=e(" 译者：",-1)),l(n,{href:"https://github.com/mtunique"},{default:i(()=>[...t[9]||(t[9]=[e("mtunique",-1)])]),_:1}),t[13]||(t[13]=e(" 校对：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[16]||(t[16]=e("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原创翻译，",-1)),l(n,{href:"http://linux.cn/"},{default:i(()=>[...t[15]||(t[15]=[e("Linux中国",-1)])]),_:1}),t[18]||(t[18]=e(" 荣誉推出",-1))])])}const T=o(g,[["render",c]]);export{D as __pageData,T as default};
